{
  "name": "Grace Minseo Han",
  "age": 38,
  "gender": "Female; she is a woman.",
  "nationality": "American; a U.S. citizen, born and raised in Washington State.",
  "residence": {
    "city": "Portland",
    "state": "Oregon",
    "living_situation": "Rents a one-bedroom apartment and lives alone. She keeps a small desk area for working from home, shelves of books, and a few plants she has learned not to overwater."
  },
  "race_ethnicity": {
    "category": "Asian",
    "heritage": "Korean American. Her parents immigrated from South Korea before she was born. She understands familiar Korean phrases used by her family but is not fluent."
  },
  "gross_household_income": {
    "annual_amount": "Approximately USD $147,000 in a typical year, including salary and a variable bonus.",
    "supplied_band": "$100,000–$199,999",
    "household_composition": "A one-person household; this income is hers rather than shared with a spouse or partner."
  },
  "partnership_status": "Single and not currently in a committed relationship. She dates occasionally, but dating is not the organizing focus of her life.",
  "children_status": "Has no children and is not a parent.",
  "education": {
    "highest_degree": "Bachelor's degree in Communication and Media Studies from the University of Washington, completed in 2010.",
    "additional_learning": "She has taken short courses in research methods and data visualization when they were useful at work. She enjoys learning through books and practical projects more than collecting formal credentials."
  },
  "long_term_goals": [
    "Build enough savings and retirement security to have more choice about when and how much she works later in life.",
    "Keep her work interesting without moving into a management role solely for status or a larger title.",
    "Stay closely involved with her parents and brother while maintaining a home and routine of her own.",
    "Travel regularly without turning every holiday into a costly or tightly scheduled production.",
    "She is undecided about buying a home and does not regard marriage or parenthood as prerequisites for a satisfying future."
  ],
  "occupation": {
    "job_title": "Senior UX researcher at a mid-sized software company.",
    "work": "She conducts interviews and usability studies, helps product teams understand how customers use their software, and presents findings to designers and engineers. She is good at noticing when a team's favored explanation is not supported by what people actually do.",
    "work_history": "After college she began as a research coordinator at a Seattle digital agency, then moved into UX research. She relocated to Portland in 2017 for a role that offered more ownership of projects. Her current job is hybrid: she works from home most days and goes to the office when in-person collaboration is useful.",
    "work_style": "She likes a clear research question and enough time to hear from a range of users. She can get impatient with meetings where people debate hypothetical customers instead of looking at evidence. She is not especially interested in managing a large team."
  },
  "style": "She speaks in a measured, conversational way and tends to be specific rather than grand. She asks practical follow-up questions when something is unclear, and uses dry humor with people she knows well. In a meeting she will usually explain her reasoning before disagreeing; with friends she is more likely to say, 'That sounds fun, but I need one quiet day in there.' She does not fill every pause and can be brief when she is tired.",
  "personality": {
    "big_five_scale": "Fictional descriptive tendencies on a 1–5 scale, where 1 is low and 5 is high; these are not psychometric test results.",
    "openness": {
      "value": 4,
      "description": "Curious about unfamiliar food, neighborhoods, and ideas. She likes trying new things when she can retain some control over the pace and does not need novelty in every part of a trip."
    },
    "conscientiousness": {
      "value": 4,
      "description": "Keeps a calendar, follows through on work commitments, and plans ahead for travel. At home she is less orderly than her work files suggest and sometimes lets laundry sit."
    },
    "extraversion": {
      "value": 3,
      "description": "Enjoys one-to-one conversation and small gatherings but needs time alone afterward. She can be sociable at work without wanting a busy social schedule every evening."
    },
    "agreeableness": {
      "value": 3,
      "description": "Considerate and generally cooperative, but not inclined to agree just to keep a conversation smooth. She is more patient with honest uncertainty than with confident claims she thinks are baseless."
    },
    "neuroticism": {
      "value": 2,
      "description": "Usually steady under ordinary stress. Unclear travel logistics or a sudden pileup of work can make her fret and overcheck details, but she tends to settle once there is a workable plan."
    }
  },
  "preferences": {
    "travel_and_vacations": {
      "desired_experience": "She wants a vacation to feel like living somewhere else briefly, not like completing a checklist. She gravitates toward walkable cities, coastal places, good local food, bookstores, museums, architecture, and quieter natural scenery. She likes having one main activity or destination on a day and room to wander around it.",
      "pace_and_planning": "Before a trip she saves places to a map and reads enough to understand neighborhoods and transit. She likes a basic structure—where she is sleeping, how she will get around, and perhaps one booked activity—but resists planning every meal and hour. She has learned that a day with several reservations makes her watch the clock instead of noticing where she is.",
      "lodging_and_transport": "She chooses clean, quiet, conveniently located small hotels or guesthouses over luxury amenities, and values a private room and a comfortable place to read. In cities she prefers walking and public transit. She will rent a car when it meaningfully opens up a rural area, but dislikes making a car the default for a city holiday.",
      "companions_and_solo_travel": "She is comfortable traveling alone and enjoys choosing her own route and stopping when something catches her attention. She also likes trips with one compatible friend; she would rather travel with someone who can split up for an afternoon than someone who expects to spend every hour together. Several solo dinners in a row can feel lonely, so she often mixes independent days with shared plans.",
      "frequency_and_time": "In a typical year she tries to take one longer trip and a few shorter getaways, with the exact mix depending on work and family obligations. A longer trip usually means using roughly a week or more of workdays off; shorter trips are often built around a weekend. She does not assume every year will include an international vacation.",
      "finances": "She puts money aside gradually for travel and treats the trip as a planned expense rather than something to pay off afterward. She is willing to spend more for a convenient location or a special meal, but is not interested in luxury for its own sake. She and a travel companion usually agree on shared lodging costs in advance, while keeping personal meals and purchases separate. She sometimes uses accumulated card points toward flights and pays her card balance in full.",
      "things_she_avoids": "She is not drawn to cruises, resort packages, large escorted tour groups, or vacations with early starts every day. Those formats are not absolute rules for her, but she prefers trips where she can change the plan without negotiating with a group."
    },
    "reading": {
      "interest": "Enjoys reading for leisure and personal interest.",
      "habits_and_tastes": "She reads contemporary fiction, essays, narrative nonfiction, and occasional books about design or social behavior. She borrows from the library, buys books she expects to revisit, and usually carries an e-reader when traveling. She often reads before bed and is prone to getting absorbed in a book when she meant to read only a chapter."
    },
    "other_leisure": [
      "Takes long neighborhood walks, especially when she has spent most of the day looking at a screen.",
      "Likes trying a recipe for friends, though weeknight dinners are often simple and repetitive.",
      "Takes occasional beginner pottery classes; she likes the tactile focus, even when the finished pieces are uneven.",
      "Enjoys day hikes when the route is not too crowded or logistically elaborate."
    ]
  },
  "beliefs": {
    "political_identification": "Libertarian.",
    "political_outlook": "She prioritizes individual liberty and is skeptical of government restrictions on both personal and economic life. Privacy, freedom of expression, and the ability to make voluntary choices matter to her. She is wary of regulation that seems broad or cumbersome, while also recognizing that concentrated private power can limit people's choices. She is not a party organizer and does not assume that every policy question has a simple libertarian answer.",
    "personal_values": "Values candor, personal responsibility, privacy, and having room to make her own decisions. She dislikes being pressured to follow a convention without a clear reason, but is willing to compromise when other people are directly affected."
  },
  "skills": [
    "Conducts user interviews and usability studies with a calm, non-leading manner.",
    "Synthesizes complicated feedback into clear findings and examples.",
    "Can explain a disagreement without turning it into a personal contest.",
    "Plans routes and travel days efficiently while leaving some unstructured time.",
    "Keeps track of shared expenses and handles ordinary trip logistics.",
    "Reads maps well and is comfortable navigating unfamiliar public transit."
  ],
  "behaviors": {
    "ordinary_week": "She works concentrated blocks in the morning, takes a walk or makes lunch away from her desk when she remembers, and reserves some evenings for reading or cooking. She sees friends for dinner or a drink about once or twice a week, but often prefers a quiet night after a demanding workday.",
    "travel_in_practice": "For a trip she starts saving months ahead, checks work deadlines before choosing dates, and makes a short list of places rather than a minute-by-minute itinerary. She usually takes her own time to explore a neighborhood, then meets a companion for dinner or a planned activity.",
    "recent_trip": "In fall 2025 she spent nine days in Tokyo and Kyoto with Nina, a college friend who lives in Seattle. They chose the lodging together, split the shared costs, and each picked several things the other might not have found. They used trains and walked extensively, visited a museum and bookstores, and left some afternoons open. Grace enjoyed having company for meals and the shared discovery, but felt that they had made too many dinner plans in advance. On her next trip she wants to leave more evenings undecided.",
    "money_and_purchases": "She checks her budget before committing to a large expense and prefers to save for travel, books, and a few quality household items rather than upgrade everything she owns. She is not a strict bargain hunter; convenience is worth paying for when it saves meaningful time or hassle."
  },
  "health": {
    "general": "Generally healthy and independent in daily life.",
    "habits": "Walking is her most consistent exercise. She sometimes does short strength or stretching sessions at home, though the habit comes and goes. Long stretches at a laptop can leave her neck and shoulders tight, so she tries to get up between calls. She sleeps reasonably well most of the time and notices that late work messages make it harder to wind down."
  },
  "relationships": {
    "family": "Her parents live in Tacoma, where she grew up. She calls them most weeks and visits when schedules allow, usually for an ordinary meal rather than a formal occasion. They remain close, though they do not always share the same expectations about work and what a settled adult life should look like.",
    "siblings": "She has an older brother who lives in the Seattle area. They get along and exchange practical help and family updates, though they are not in constant contact. She is fond of his young child and enjoys being an aunt without wanting to parent herself.",
    "friends": "She has a small circle of long-standing friends, including Nina, her college friend and occasional travel companion. She is reliable about showing up for important moments but does not need frequent group plans to feel connected.",
    "romantic_life": "She has had relationships in the past and is open to dating, but currently lives independently and makes plans without assuming a partner will join. She is comfortable with her single status and can still feel occasional curiosity about what a different kind of partnership might be like."
  },
  "other_facts": {
    "work_and_location_history": "Growing up in Tacoma and attending college in Seattle gave her long familiarity with Washington; moving to Portland as an adult was a deliberate change of city, not a move to follow a partner.",
    "household_finances": "She is the sole earner in her household. Her income is steady enough to cover rent, ordinary expenses, savings, and planned travel, though she pays attention to larger discretionary purchases and does not treat every year as equally flexible."
  }
}

